Template = GetCommonTemplate("InvoiceKO1");
Sheet = New SpreadsheetDocument();
Sheet.Put(Template.GetArea("Header"));
Sheet.Show("Invoice");

Sheet.Put(Template.GetArea("Header"));
For Each Line In Goods Do
    Sheet.Put(Template.GetArea("Row|Number"));
    Sheet.Join(Template.GetArea("Row|Goods"));
EndDo;

Head = Template.GetArea("Header");
Head.Parameters.Number = Ref.Number;
Head.Parameters.TotalAmount = Format(Total, "NFD=2");
Sheet.Put(Head);

Cell = Sheet.Area(1, 1);
Message(Cell.Value);              // прочитати назад
Cell.Value = "Report title";
Cell.AlignHorizontal = SpreadsheetHorizontalAlignment.Center;
Cell.Font = New Font("Arial", 10, True);

For Each Ref In Documents Do
    If Not First Then
        Sheet.PutHorizontalPageBreak();
    EndIf;
    First = False;
    PrintOne(Sheet, Ref);
EndDo;

Sheet.Put(Template.GetArea("GroupHeader"));
Sheet.BeginRowGroup();
For Each Line In Rows Do
    Sheet.Put(Template.GetArea("Row"));
EndDo;
Sheet.EndRowGroup();
